import SwiftUI
import AppKit

struct FieldView: View {
    @EnvironmentObject var work:Workspace
    let field:Field;var source="metrics";var prominent=false
    var body:some View{HStack(alignment:.firstTextBaseline,spacing:6){VStack(alignment:.leading,spacing:5){Text(field.label).font(.caption).foregroundStyle(.secondary);Text(field.text).font(prominent ? .title2.bold():.body).monospacedDigit().textSelection(.enabled).lineLimit(3)};Spacer(minLength:1);Button{work.explain(field,source:source)}label:{Image(systemName:"questionmark.circle").foregroundStyle(.secondary)}.buttonStyle(.plain).help("Explain this value, its source, and available controls")}}
}
struct JsonPane:View {let title:String;let value:Any;var source="";@State private var tree=true;var body:some View{VStack(alignment:.leading,spacing:8){HStack{Text(title).font(.headline);Spacer();Picker("",selection:$tree){Text("Tree").tag(true);Text("Raw JSON").tag(false)}.pickerStyle(.segmented).frame(width:175)};if tree{JsonTree(value:value,source:source)}else{ScrollView{Text(Workspace.pretty(value)).font(.system(.caption,design:.monospaced)).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading).padding(10)}}}.frame(maxWidth:.infinity,maxHeight:.infinity)}}
struct StudioView:View {
    @ObservedObject var panel:Panel;@StateObject var work=Workspace();@State private var action="";@State private var confirm=false
    var section:String{get{work.section} nonmutating set{work.section=newValue}}
    var body:some View{GeometryReader { geometry in VStack(spacing:0) { NavigationSplitView{List(selection:$work.section){Section("Workspace"){Label("Overview",systemImage:"square.grid.2x2").tag("Overview");Label("Data sources",systemImage:"externaldrive.connected.to.line.below").tag("Sources");Label("Data explorer",systemImage:"tablecells").tag("Explorer");Label("Datasets & links",systemImage:"point.3.connected.trianglepath.dotted").tag("Datasets");Label("Flows & validation",systemImage:"arrow.triangle.branch").tag("Flows");Label("Agent sessions",systemImage:"text.bubble").tag("Agents")};Section("Processing instance"){Label("Stages",systemImage:"list.bullet.rectangle").tag("Stages");Label("Usage & estimates",systemImage:"chart.bar").tag("Tokens");Label("Logs",systemImage:"terminal").tag("Logs")}}.navigationTitle("Pipeline").navigationSplitViewColumnWidth(225)}detail:{VStack(alignment:.leading,spacing:14){HStack{VStack(alignment:.leading){Text(section == "Tokens" ? "Usage & estimates" : section).font(.largeTitle.bold());Text(section=="Stages"||section=="Tokens"||section=="Logs" ? "Pinned processing instance · \(panel.partition)" : "Local data workspace · live source observation").font(.caption).foregroundStyle(.secondary)};Spacer();Button{Task{await refresh()}}label:{Image(systemName:"arrow.clockwise")}.help("Read current source databases and process state")};if !panel.error.isEmpty{Label(panel.error,systemImage:"exclamationmark.triangle.fill").foregroundStyle(.red).textSelection(.enabled)};if !work.error.isEmpty{HStack{Image(systemName:"exclamationmark.triangle.fill");Text(work.error).textSelection(.enabled);Spacer();Button("Dismiss"){work.error=""}}.foregroundStyle(.red)};if !work.notice.isEmpty{Text(work.notice).font(.caption).textSelection(.enabled).foregroundStyle(.secondary)}
      Group{switch section{case "Overview":overview;case "Sources":SourcesView();case "Explorer":ExplorerView();case "Datasets":DatasetsView();case "Flows":FlowsView();case "Agents":AgentsView();case "Stages":stages;case "Tokens":tokens;default:logs}}.environmentObject(work)
    }.padding(18).frame(maxWidth:.infinity,maxHeight:.infinity).navigationTitle(section)}.frame(maxWidth:.infinity,maxHeight:.infinity).clipped().environmentObject(work)
    TerminalDock(maxHeight:geometry.size.height * 0.4).environmentObject(work)
    } }.frame(minWidth:1080,minHeight:720)
    .sheet(item:$work.help){_ in HelpSheet().environmentObject(work)}
    .onChange(of:work.selectedSession){_,value in if !value.isEmpty{section="Agents"}}
    .task{await work.refresh();await work.datasets();await work.agents()}
    .task(id:section){await refresh();while !Task.isCancelled{try? await Task.sleep(for:.seconds(section=="Agents" ? 2:5));if Task.isCancelled{break};await refresh()}}
    .confirmationDialog(action=="restart" ? "Restart this pinned processing instance from checkpoints?":"Pause this pinned processing instance?",isPresented:$confirm){Button(action=="restart" ? "Restart":"Pause"){Task{await panel.call("pause");if action=="restart"&&panel.error.isEmpty{await panel.call("resume")};await panel.call("status")}}}
    }
    func refresh()async{switch section{case "Agents":await work.agents();await work.pollSession();case "Datasets","Flows":await work.datasets();case "Overview":await panel.call("status");await work.refresh();case "Stages","Tokens":await panel.call("status");case "Logs":await panel.call("logs");default:await work.refresh()}}
    var overview:some View{ScrollView{VStack(alignment:.leading,spacing:18){controls;HStack(spacing:12){card(Field("run.completed","Completed jobs",panel.completed,meaning:"Durably completed stage jobs, not fully processed files."));card(Field("run.pending","Queued jobs",panel.pending,meaning:"Jobs waiting for processing."));card(Field("run.failed","Failed jobs",panel.failed,meaning:"Jobs with persisted failure state."))};HStack{Button("Review processing stages"){section="Stages"};Button("Browse collected data"){section="Explorer"};Button("Review usage"){section="Tokens"}};HStack(spacing:12){card(Field("sources.registered","Registered sources",work.sources.count,meaning:"Sources explicitly registered in this workspace."));card(Field("sources.active","Verified active workers",work.sources.filter{$0.alive==true}.count,meaning:"Workers whose current process identity matches source registration."));card(Field("sources.stale","Stale observations",work.sources.filter{$0.stale}.count,meaning:"Checkpoints older than the configured freshness threshold. This is separate from process liveness."));card(Field("datasets.revisions","Dataset revisions",work.revisions.count,meaning:"Immutable reviewed or transformed dataset revisions."))};Text("Collection and processing are separate").font(.title3.bold());Text("Sources show live collector state and durable request/file counts. Datasets contain reviewed revisions. Processing stages belong to their pinned execution instance; editing a draft never changes a running instance.").foregroundStyle(.secondary);ForEach(work.sources){source in SourceSummary(source:source)};FieldView(field:Field("workspace.observed","Observed at",work.observed,meaning:"Time the workspace last read source metadata and databases.",observed:work.observed))}}}
    func card(_ field:Field)->some View{FieldView(field:field,prominent:true).padding(16).frame(maxWidth:.infinity).background(.quaternary,in:RoundedRectangle(cornerRadius:12))}
    var controls:some View {
      VStack(alignment:.leading,spacing:12) {
        HStack(spacing:14) {
          Image(systemName:panel.alive ? "waveform.path":"pause.circle.fill").font(.title2).foregroundStyle(panel.alive ? .green:.orange)
          VStack(alignment:.leading,spacing:4) {
            Text(panel.partition + " · " + panel.phase.capitalized).font(.headline)
            Text(panel.alive ? "A controller is active. Stage counts below show durable progress." : "No controller is running. Resume continues from saved checkpoints.").font(.callout).foregroundStyle(.secondary)
          }
          Spacer()
          if panel.busy { ProgressView().controlSize(.small); Text("Contacting pipeline…").font(.caption).foregroundStyle(.secondary) }
          else if panel.alive {
            Button("Pause processing",systemImage:"pause.fill"){action="pause";confirm=true}
          } else {
            Button("Resume processing",systemImage:"play.fill"){Task{await panel.call("resume");await panel.call("status")}}.buttonStyle(.borderedProminent)
          }
          Menu {
            Button("Refresh status"){Task{await panel.call("status")}}
            Button("View logs"){section="Logs"}
            Button("Restart from checkpoint"){action="restart";confirm=true}.disabled(panel.busy)
          } label:{Image(systemName:"ellipsis.circle")}.menuStyle(.borderlessButton).fixedSize()
        }
        if panel.failed > 0 { Button("\(panel.failed.formatted()) failed jobs · Review logs",systemImage:"exclamationmark.triangle"){section="Logs"}.foregroundStyle(.orange) }
        if panel.busy { Text("Controls return when this request finishes. No processing action is started by refreshing.").font(.caption).foregroundStyle(.secondary) }
      }.padding(18).background(.quaternary.opacity(0.45),in:RoundedRectangle(cornerRadius:14))
    }
    var stages:some View{VStack(alignment:.leading){controls;if !panel.error.isEmpty{Text(panel.error).foregroundStyle(.red)};List(Array(panel.roles.enumerated()),id:\.offset){_,stage in VStack(alignment:.leading){FieldView(field:Field("stage."+stage.0,stage.0.capitalized,"\(stage.1) / \(stage.2)",meaning:stage.2==0 ? "No jobs have materialized for this stage; this is not an ETA.":"Durable completed jobs divided by materialized jobs for this stage.",origin:panel.bridge.config));ProgressView(value:stage.2>0 ? Double(stage.1)/Double(stage.2):0);Button("Review stage output"){Task{await panel.call("sample",role:stage.0);work.notice="Stage sample loaded from the pinned processing database."}}}};JsonPane(title:"Stage output",value:(try? JSONSerialization.jsonObject(with:Data(panel.sample.utf8))) ?? ["message":panel.sample],source:"Pinned stage output")}}
    var tokens:some View{VStack(alignment:.leading,spacing:18){controls;UsageView(panel:panel)}}
    var logs:some View{VStack(alignment:.leading){controls;Text("Local logs from the pinned processing instance. Source collectors have independent checkpoints in Data sources.").font(.caption).foregroundStyle(.secondary);ScrollView{Text(panel.logs).font(.system(.caption,design:.monospaced)).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading)};Button("Explain log state"){work.explain(Field("run.logs","Processing log", "Bounded local log tail",meaning:"Last 200 lines / 64 KiB of the pinned instance log; not a collector progress feed.",origin:panel.bridge.config),source:"metrics")}}}
}
struct SourceSummary:View {
 @EnvironmentObject var work:Workspace;let source:SourceCard
 var body:some View{VStack(alignment:.leading,spacing:12){HStack{Image(systemName:source.alive==true ? "circle.fill":"circle").foregroundStyle(source.alive==true ? .green:.secondary);Text(source.name).font(.headline);Spacer();if source.stale{Label("Stale checkpoint",systemImage:"clock.badge.exclamationmark").foregroundStyle(.orange)};Button{work.explain(Field("source.identity",source.name,source.id,meaning:"Explicit source registration; counts and process state come from this source only.",origin:source.root,observed:source.observed))}label:{Image(systemName:"questionmark.circle")}.buttonStyle(.plain)};HStack{FieldView(field:Field("source.phase","Collector state",source.phase,meaning:"Latest source checkpoint state. A running process is verified separately.",origin:source.root,observed:source.observed));FieldView(field:Field("source.alive","Worker verified",source.alive.map{$0 ? "Running":"Stopped"} ?? "Unknown",meaning:"Process liveness checked against registered identity; a PID alone is not proof.",origin:source.root,observed:source.observed));FieldView(field:Field("source.age","Checkpoint age",source.age.map{String(format:"%.0f seconds",$0)} ?? "Unknown",meaning:"Age of collector checkpoint evidence, independently of its process state.",origin:source.root,observed:source.observed));FieldView(field:Field("source.updated","Checkpoint updated",source.updated,meaning:"Timestamp recorded by the collector. Old snapshots stay labeled with their age.",origin:source.root,observed:source.observed))};LazyVGrid(columns:[GridItem(.adaptive(minimum:180))],alignment:.leading,spacing:14){ForEach(source.metrics){field in FieldView(field:field)}};ForEach(source.errors,id:\.self){Text($0).font(.caption).foregroundStyle(.orange).textSelection(.enabled)}}.padding(16).background(.quaternary.opacity(0.5),in:RoundedRectangle(cornerRadius:12))}
}
struct SourcesView:View{@EnvironmentObject var work:Workspace;var body:some View{ScrollView{LazyVStack(spacing:14){ForEach(work.sources){source in VStack(alignment:.leading){SourceSummary(source:source);HStack{Text(source.root).font(.caption.monospaced()).foregroundStyle(.secondary).textSelection(.enabled);Spacer();Button("Show in Finder"){NSWorkspace.shared.selectFile(nil,inFileViewerRootedAtPath:source.root)}}.padding(.horizontal,8)}}}}}}
struct HelpSheet:View{
 @EnvironmentObject var work:Workspace
 var body:some View{VStack(alignment:.leading,spacing:16){HStack{Label("Field assistance",systemImage:"questionmark.bubble").font(.title2.bold());Spacer();Button("Close"){work.help=nil}};Text("A fresh agent session gets only the packet below. It does not inherit this engineering chat. The selected provider receives this packet when you press Ask.").font(.callout).foregroundStyle(.secondary);Picker("Agent",selection:$work.provider){ForEach(work.providers,id:\.providerId){p in Text((p["id"] as? String ?? "Agent")+((p["available"] as? Bool)==false ? " · unavailable":"")).tag(p["id"] as? String ?? "")}};if work.helpSource != "metrics" && !work.helpSource.isEmpty{Toggle("Include the displayed field value",isOn:$work.helpInclude).onChange(of:work.helpInclude){_,_ in Task{await work.prepareHelp()}}};TextEditor(text:$work.helpPacket).font(.system(.caption,design:.monospaced)).frame(minHeight:220);ForEach(work.helpSuggestions,id:\.self){Text("• "+$0).font(.caption)};HStack{Button("Copy prompt"){NSPasteboard.general.clearContents();NSPasteboard.general.setString(work.helpPacket,forType:.string)};Spacer();Button("Ask \(work.provider.capitalized)"){Task{await work.askHelp()}}.buttonStyle(.borderedProminent).disabled(work.helpPacket.isEmpty)}}.padding(24).frame(width:690,height:620)}
}
extension Dictionary where Key==String,Value==Any{var providerId:String{self["id"] as? String ?? ""}}
